package com.cyberpath.learning;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.provider.OpenableColumns;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

/** Native component integration checks on the dedicated fresh audit emulator. */
public final class NativeAddonsSmoke {
 private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 private static void waitIncoming(MainActivity.NativeBridge bridge)throws Exception{for(int i=0;i<100;i++){if(!new JSONObject(bridge.getIncomingStatus()).optBoolean("reading"))return;SystemClock.sleep(50);}throw new AssertionError("Incoming file did not finish reading");}
 private static void incoming(Instrumentation test,MainActivity activity,Intent intent){test.runOnMainSync(()->test.callActivityOnNewIntent(activity,intent));}
 public static void run(Instrumentation test,MainActivity activity,Bundle report)throws Exception{
  Context context=test.getTargetContext();MainActivity.NativeBridge bridge=activity.new NativeBridge();String profile=bridge.getActiveProfile();
  JSONObject lock=new JSONObject(bridge.getAppLockStatus());require(lock.has("secure")&&!lock.getBoolean("enabled"),"App lock should be off on a fresh install");report.putBoolean("app_lock_default_off_and_os_status",true);
  ServiceInfo tile=context.getPackageManager().getServiceInfo(new ComponentName(context,QuickNoteTile.class),0);require(tile.exported&&"android.permission.BIND_QUICK_SETTINGS_TILE".equals(tile.permission),"Quick note tile is not protected by the system binding permission");
  ProviderInfo capture=context.getPackageManager().getProviderInfo(new ComponentName(context,PageCaptureProvider.class),0);require(!capture.exported&&capture.grantUriPermissions,"Page camera provider grants are too broad");
  Uri photo=PageCaptureProvider.create(context);require(!PageCaptureProvider.ready(context,photo),"An empty camera file was accepted");try(OutputStream output=context.getContentResolver().openOutputStream(photo,"w")){output.write(new byte[]{(byte)0xff,(byte)0xd8,(byte)0xff,(byte)0xd9});}require(PageCaptureProvider.ready(context,photo),"Camera photo could not be read back");
  try(InputStream in=context.getContentResolver().openInputStream(photo)){require(in.read()==255,"Camera provider lost the file bytes");}
  Uri invalid=Uri.parse("content://"+context.getPackageName()+".capture/../../studio-workspace.json");try(InputStream ignored=context.getContentResolver().openInputStream(invalid)){throw new AssertionError("Camera provider allowed a workspace path");}catch(FileNotFoundException expected){}
  report.putBoolean("camera_provider_roundtrip_and_path_boundary",true);report.putBoolean("quick_settings_service_registration",true);
  Intent text=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"A private native intake fixture");incoming(test,activity,text);waitIncoming(bridge);JSONObject packet=new JSONObject(bridge.readIncoming(profile));require(packet.getString("text").equals("A private native intake fixture"),"Shared text was changed");require(new JSONObject(bridge.readIncoming("foreign-profile")).has("nativeError"),"Shared text leaked to a stale profile");bridge.dismissIncoming(packet.getString("token"),profile);require(!new JSONObject(bridge.getIncomingStatus()).optBoolean("ready"),"Reviewed intake was not dismissed");
  Uri document=Uri.parse("content://com.lw.releasecheck.incoming/42");Intent file=new Intent(Intent.ACTION_VIEW).setDataAndType(document,"application/octet-stream").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);incoming(test,activity,file);waitIncoming(bridge);packet=new JSONObject(bridge.readIncoming(profile));require("sample.course.v1.LW".equals(packet.getString("name"))&&TestShareProvider.TEXT.equals(packet.getString("text")),"Opaque provider course intake failed");bridge.dismissIncoming(packet.getString("token"),profile);
  incoming(test,activity,new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://com.lw.releasecheck.incoming/bad"),"application/octet-stream"));waitIncoming(bridge);require(!new JSONObject(bridge.getIncomingStatus()).optBoolean("ready"),"A non-.lw file was accepted by direct course opening");
  incoming(test,activity,new Intent(Intent.ACTION_VIEW,Uri.parse("https://example.invalid/course.lw")));waitIncoming(bridge);require(!new JSONObject(bridge.getIncomingStatus()).optBoolean("ready"),"Remote URI was accepted as a local course");require(new JSONObject(bridge.getState(profile)).getJSONObject("courses").length()==0,"Receiving content imported a course without review");report.putBoolean("profile_bound_text_and_opaque_file_intake",true);report.putBoolean("unsafe_uri_and_automatic_import_refused",true);
  for(String path:new String[]{"course.lw","sample.course.v1.LW","opaque/42"}){Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://com.lw.releasecheck.incoming/"+path),"application/octet-stream").addCategory(Intent.CATEGORY_DEFAULT).setPackage(context.getPackageName());require(!context.getPackageManager().queryIntentActivities(view,PackageManager.MATCH_DEFAULT_ONLY).isEmpty(),"Open-with LW does not resolve this file-provider path: "+path);}report.putBoolean("direct_lw_association_for_opaque_provider_paths",true);
 }
 public static void focus(Context context,Bundle report)throws Exception{java.util.concurrent.CountDownLatch drained=new java.util.concurrent.CountDownLatch(1);NativeServices.IO.execute(drained::countDown);require(drained.await(10,java.util.concurrent.TimeUnit.SECONDS),"Native jobs did not settle");
  JSONObject synthetic=AppFiles.workspace(context),focus=new JSONObject().put("preferences",new JSONObject().put("notify",true)).put("sessions",new JSONArray().put(new JSONObject().put("id","native-focus-check").put("startedAt",java.time.Instant.now().toString()).put("minutes",5).put("intention","A native countdown fixture").put("endedAt","")));synthetic.getJSONObject("learning").put("focus",focus);FocusNotification.sync(context,synthetic);android.service.notification.StatusBarNotification found=null;for(int i=0;i<30&&found==null;i++){for(android.service.notification.StatusBarNotification row:context.getSystemService(NotificationManager.class).getActiveNotifications())if(row.getId()==907)found=row;if(found==null)SystemClock.sleep(50);}require(found!=null&&found.getNotification().extras.getBoolean(Notification.EXTRA_SHOW_CHRONOMETER)&&found.getNotification().extras.getBoolean(Notification.EXTRA_CHRONOMETER_COUNT_DOWN),"System focus countdown was not posted");focus.getJSONArray("sessions").getJSONObject(0).put("endedAt",java.time.Instant.now().toString());FocusNotification.sync(context,synthetic);boolean remained=true;for(int i=0;i<30&&remained;i++){remained=false;for(android.service.notification.StatusBarNotification row:context.getSystemService(NotificationManager.class).getActiveNotifications())if(row.getId()==907)remained=true;if(remained)SystemClock.sleep(50);}require(!remained,"Ended focus notification remained");report.putBoolean("native_focus_countdown_post_and_cancel",true);
 }
 public static void archive(Context context,String profile,String expectedActive,Bundle report)throws Exception{String active=ProfileFiles.active(context);JSONObject payload=new JSONObject(ProfileArchive.export(context,profile));require(ProfileFiles.active(context).equals(active)&&active.equals(expectedActive),"All-profile export switched the active profile");require(payload.getJSONArray("localFiles").length()==1,"All-profile export lost an attachment");require(!payload.toString().contains("privateKey"),"Profile archive included a signing key");report.putBoolean("read_only_other_profile_archive_with_file",true);}
}
